mapper.select:
SELECT  FROM expression_basis_review
WHERE owner_id=#{owner} AND item_id=#{itemId}
AND revision < #{before}
ORDER BY revision DESC LIMIT #{limit}

mapper.update:
UPDATE preparation_item SET revision=revision+1,source_generation=source_generation+1,updated_at=#{now}
WHERE owner_id=#{owner} AND id=#{itemId} AND kind='EXPRESSION' AND status='ACTIVE'
  AND revision=#{expected} AND current_version_id=#{versionId}
  AND revision < 9007199254740991 AND source_generation < 9007199254740991
